import { type ClassValue, clsx } from 'clsx';
import DOMPurify from 'dompurify';

export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

/** Cria um elemento HTML com atributos e filhos. */
export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs: Record<string, string> = {},
  ...children: (string | Node)[]
): HTMLElementTagNameMap[K] {
  const element = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    element.setAttribute(key, value);
  }
  for (const child of children) {
    if (typeof child === 'string') {
      element.appendChild(document.createTextNode(child));
    } else {
      element.appendChild(child);
    }
  }
  return element;
}

/**
 * Renderiza HTML string num container, sanitizando antes via `DOMPurify.sanitize`.
 *
 * O sanitizer remove <script>, <style>, <iframe>, event handlers on*, e
 * neutraliza `href/src/action="javascript:..."`. Para HTML 100% confiável
 * (string literal estática), o overhead de re-parse é desprezível.
 */
export function renderHtml(container: Element, html: string): void {
  container.innerHTML = DOMPurify.sanitize(html);
}

/*
 * ─── Temas de Marca ───────────────────────────────────────────────────────────
 * Default, Warm e Cold. Cada um declara os 39 tokens de cor dentro de
 * `.tema-<id>` e `.dark.tema-<id>`; `tokens.css` não tem cor nenhuma.
 *
 * O Default NÃO é ausência de classe — foi, e a duplicação que isso exigia
 * acabou divergindo. Sem uma classe `tema-*` no `<html>`, não há cor.
 *
 * A ORDEM importa menos do que parece, e é bom que continue assim: nenhum
 * consumidor deve depender de duas classes de tema conviverem no mesmo
 * elemento. Quem aplica remove a anterior antes de somar a nova.
 *
 * Todos os projetos importam via: @import "@shared/themes/index.css"
 */
@import "./default.css";
@import "./warm.css";
@import "./cold.css";
@import "./densities.css";
@import "./fonts.css";
@import "./typescale.css";

/*
 * ─── Tema: Warm ───────────────────────────────────────────────────────────────
 * Variante de cores quentes do tema Default.
 *
 * Estratégia:
 *   - Neutros (background, foreground, secondary, muted, accent, border) ganham
 *     tint âmbar/marrom sutil (matiz ~30°, saturação 8–15%) — continuam "quase
 *     cinzas", mas a tela tem temperatura quente. É AQUI que mora a identidade
 *     do tema, e é por isso que ela sobrevive a status frios.
 *   - Marca: `--primary` é vermelho vivo.
 *   - Status: NÃO seguem o semáforo, e não por estilo. Com a marca ocupando o
 *     vermelho, o alarme não pode ficar lá — o vermelho passa a ser a cor mais
 *     frequente da tela (botão, link, foco, estado ativo), e alarme que aparece
 *     o tempo todo deixa de ser alarme. O erro migra para MAGENTA; o info sai do
 *     laranja e vai para AZUL; sucesso (verde) e aviso (âmbar) ficam, porque não
 *     disputam nada com um primary vermelho e trocá-los custaria compreensão
 *     sem comprar separação.
 *
 *     A semântica não fica pendurada na convenção de matiz: todo contêiner de
 *     feedback pareia cor com ÍCONE e TÍTULO, e é por isso que `warning` e
 *     `info` têm piso de 3:1 em vez de 4.5 — a cor deles pinta o ícone, não o
 *     texto corrido. O que a cor precisa ser é inconfundível, e o critério
 *     passa a ser distância, não costume.
 *
 *     Três status ficam FRIOS num tema de neutros quentes, e isso é a favor:
 *     eles viram a única coisa fria da tela, que é a saliência que um alerta
 *     precisa ter.
 *   - Charts: oito séries da paleta de sintaxe do code-block, com variante por
 *     modo. Não saem mais da paleta deste tema — a razão está no bloco
 *     `--chart-*`, e é de contraste, não de estilo.
 *   - Radius, dimensões e shadows herdam de tokens.css (Default).
 *
 * O que ESTE arquivo dizia antes, e por que estava errado: "feedback colors
 * deslocam suavemente para o lado quente do espectro". Deslocavam — e o
 * resultado medido era `warning × info` a 4° de matiz no claro e `primary ×
 * info` a 2° no ESCURO, ou seja, a cor de informação era a cor da marca.
 * Quatro significados num arco de 24°. Hoje a menor separação entre os cinco é
 * 37° no claro e 42° no escuro.
 *
 * Contraste, mesma conta do Default — contraste(cor, composição(cor a 10%,
 * superfície)), sobre a página e sobre `--muted`, o pior dos dois:
 *
 *   claro   destructive 5.33 · success 4.65  (min 4.5)
 *           warning     3.70 · info    5.43  (min 3)
 *   escuro  destructive 4.69 · success 6.26  (min 4.5)
 *           warning     7.02 · info    4.74  (min 3)
 *
 * Como traço de 2px da badge, contra a página, todos entre 4.55 e 10.84 — piso
 * de 3:1 (WCAG 1.4.11). Botão preenchido, primary × primary-foreground: 5.42 no
 * claro e 5.45 no escuro.
 *
 * Dois limites que a medição impôs, e que parecem arbitrários sem eles: o âmbar
 * do claro é ESCURO (32%) porque a página é quase branca e ele precisa de 3:1 —
 * sete âmbares mais claros foram testados e todos reprovam. E ele fica na faixa
 * laranja-âmbar, não no amarelo: amarelo escurecido dessatura para oliva.
 *
 * Aplicado via classe `.tema-warm` no <html>. Dark mode combina com `.dark`.
 */

.tema-warm {
  /* Surfaces — tint âmbar muito sutil */
  --background: 30 25% 99%;
  --foreground: 25 20% 8%;
  --card: 30 25% 99%;
  --card-foreground: 25 20% 8%;
  --popover: 30 25% 99%;
  --popover-foreground: 25 20% 8%;

  /* Brand / Interactive — primary terracota saturado; secondary/accent creme âmbar */
  --primary: 4 78% 44%;             /* #c82419 — vermelho vivo da marca */
  --primary-foreground: 30 30% 98%;
  --secondary: 35 55% 92%;          /* creme âmbar claro */
  --secondary-foreground: 4 55% 24%;
  --muted: 30 20% 95%;
  --muted-foreground: 25 12% 42%;
  /* Valor CHEIO: o alfa é escrito no componente (0.2 nas folhas, 0.8 nas quatro
     regras .dark), então o token guarda o tom e não a aparência final. Este
     valor foi resolvido para compor, a 20% sobre a página, exatamente o pálido
     opaco que este tema mostrava antes — a aparência não mudou. */
  --accent: 34 65% 68%;
  --accent-foreground: 4 55% 24%;

  /* Feedback — paleta quente */
  /* Os quatro `-foreground` são o texto corrido do contêiner colorido, e neste
     projeto valem `--foreground` — a regra da casa. São ponto de extensão: um
     tema derivado pode dar a cada um valor próprio. Ver tokens.css. */
  --destructive: 326 72% 38%;   /* #a71b6a */
  --destructive-foreground: var(--foreground);
  --success: 155 72% 26%;       /* #13724a */
  --success-foreground: var(--foreground);
  --warning: 38 100% 32%;       /* #a36700 */
  --warning-foreground: var(--foreground);
  --info: 214 80% 38%;          /* #1357ae */
  --info-foreground: var(--foreground);

  /* Structure */
  --border: 30 15% 88%;
  --input: 30 15% 54%;              /* 3.27:1 sobre --background; matiz quente preservado */
  --input-background: 30 25% 99%;
  --ring: 4 78% 50%;                /* acompanha o primary, meio ponto mais claro */

  /* Charts — oito séries, com variante por MODO (o bloco escuro fica no fim do
     `.dark.tema-*`).

     Vêm da paleta de sintaxe do code-block, e a escolha é estrutural: ela já
     tinha valores por modo, enquanto a paleta de gráfico antiga era declarada só
     no claro e a MESMA cor precisava servir à página quase branca e ao fundo
     quase preto. Nessa janela, uma das séries do Default acabava com contraste
     1.00 contra o fundo escuro — a cor do próprio fundo, invisível.

     Medido nos três temas: pior contraste 7.32 no claro e 6.83 no escuro. A
     ordem não é arbitrária — cada série é a que MAIS se afasta das anteriores em
     matiz, então a menor separação dentro das cinco primeiras é 38°, e dentro
     das oito, 20°, que é o limite da paleta. Reordenar aproxima séries vizinhas.

     Os graus são de matiz em OKLCH, não em HSL. Dizer isso não é preciosismo:
     recalcular a partir dos números HSL declarados acima dá outros valores, e
     quem tentar conferir vai concluir que a conta está errada. HSL não é
     perceptualmente uniforme — 20° de matiz ali significam distâncias muito
     diferentes dependendo de onde se está na roda.

     Ficam no TEMA, e não em tokens.css: um tema derivado pode querer paleta
     própria de gráfico, e o contrato de tema é o lugar dessa liberdade. */
  --chart-1: 350 72% 36%;
  --chart-2: 190 88% 23%;
  --chart-3: 265 64% 41%;
  --chart-4: 145 62% 23%;
  --chart-5: 215 72% 34%;
  --chart-6: 25 88% 28%;
  --chart-7: 288 52% 36%;
  --chart-8: 200 85% 26%;

  /* Sidebar — tint quente */
  --sidebar: 30 25% 98%;
  --sidebar-foreground: 25 20% 8%;
  --sidebar-primary: 4 78% 44%;
  --sidebar-primary-foreground: 30 30% 98%;
  --sidebar-accent: 35 55% 92%;
  --sidebar-accent-foreground: 4 55% 24%;
  --sidebar-border: 30 15% 85%;
  --sidebar-ring: 4 78% 50%;

  /* Radius — a identidade de forma deste tema é o CANTO GENEROSO: 24px de base,
     contra os 14px do default. O cartão vai a 28px, e botão e campo ficam
     nitidamente mais macios sem virar cápsula.

     Duas tentativas anteriores, e as duas ensinaram: `var(--radius-full)`
     colapsava a escala inteira no pill e fazia cartão grande virar estádio; 2rem
     ainda deixava a forma competindo com o conteúdo. 1.5rem é onde ela lê como
     identidade e para de chamar atenção para si.

     Sobrescreve a BASE, e não os degraus: a escala continua derivando sozinha,
     como o contrato manda.

     Raio de pai grande expõe filho que repita o raio em vez de descontar o inset
     (Rᵢ = Rₑ − E) — foi assim que o defeito das docs pages apareceu. Está
     corrigido com `.nds-card-nested` e guardado pela regra
     `card_aninhado_sem_desconto`. */
  --radius: 1.5rem;
}

/* Dark mode — combina `.dark.tema-warm` */
.dark.tema-warm {
  --background: 25 15% 9%;
  --foreground: 30 20% 96%;
  --card: 25 15% 9%;
  --card-foreground: 30 20% 96%;
  --popover: 25 15% 9%;
  --popover-foreground: 30 20% 96%;
  --primary: 8 88% 62%;             /* #f36049 */
  --primary-foreground: 25 30% 10%;
  --secondary: 25 20% 18%;          /* marrom escuro saturado */
  --secondary-foreground: 35 55% 90%;
  --muted: 25 10% 16%;
  --muted-foreground: 30 12% 70%;
  /* Cheio, mesmo motivo do claro. 48% e não 50%: a 50% os quatro casos de
      davam 4,36:1 com a tinta clara por cima, abaixo do piso; a 48% vão
     a 4,64:1, e a aparência a 20% fica indistinguível (razão 1,014). */
  --accent: 23 28% 48%;
  --accent-foreground: 35 55% 90%;
  --destructive: 328 82% 70%;   /* #f174b7 */
  --destructive-foreground: var(--foreground);
  --success: 155 60% 56%;       /* #4bd29a */
  --success-foreground: var(--foreground);
  --warning: 45 92% 56%;        /* #f6c228 */
  --warning-foreground: var(--foreground);
  --info: 212 85% 66%;          /* #5fa3f2 */
  --info-foreground: var(--foreground);
  --border: 25 10% 16%;
  --input: 25 10% 41%;              /* 3.26:1 sobre --background; matiz quente preservado */
  --input-background: 25 15% 9%;
  --ring: 8 88% 56%;
  --sidebar: 25 15% 9%;
  --sidebar-foreground: 30 20% 96%;
  --sidebar-primary: 8 88% 62%;
  --sidebar-primary-foreground: 25 30% 10%;
  --sidebar-accent: 25 20% 18%;
  --sidebar-accent-foreground: 35 55% 90%;
  --sidebar-border: 25 10% 16%;
  --sidebar-ring: 8 88% 56%;

  /* Charts — agora COM variante escura. Antes eram declarados só no bloco
     claro, e a mesma cor tinha de servir à página quase branca e ao fundo
     quase preto: no Default isso deixava uma série com contraste 1.00, a cor
     do próprio fundo. */
  --chart-1: 350 82% 80%;
  --chart-2: 190 72% 68%;
  --chart-3: 265 82% 82%;
  --chart-4: 145 52% 70%;
  --chart-5: 215 88% 78%;
  --chart-6: 25 88% 72%;
  --chart-7: 288 68% 82%;
  --chart-8: 200 80% 72%;
}

/*
 * ─── Tema: Cold ───────────────────────────────────────────────────────────────
 * Variante de cores frias do tema Default.
 *
 * Estratégia:
 *   - Neutros (background, foreground, secondary, muted, accent, border) ganham
 *     tint azul/cyan sutil (matiz ~210°, saturação 8–15%) — continuam "quase
 *     cinzas", mas a tela tem temperatura fria. É aqui que mora a identidade do
 *     tema.
 *   - Marca: #38cdff, um cyan claro.
 *
 *     E ele NÃO pode ser o `--primary` do modo claro. O sistema lê esse token
 *     como TEXTO em 13 regras e como BORDA em 7, e #38cdff mede 1.81:1 contra a
 *     página clara — um link ali é ilegível. Como preenchimento com texto
 *     escuro ele dá 10.02:1, ou seja, o problema não é a cor, é o uso.
 *
 *     Então o primary muda de luminosidade entre os modos, como o Default já
 *     faz: no ESCURO é #38cdff literal; no CLARO é o mesmo cyan escurecido
 *     (195 90% 32%), a 3° de matiz da marca em OKLCH. Quem "corrigir" o claro
 *     para o hex da marca reintroduz o defeito.
 *   - Status: não seguem o semáforo, e é o ESPELHO do que o Warm faz. Lá a
 *     marca tomou o vermelho e o ERRO teve de sair; aqui a marca toma o cyan e
 *     quem sai é o INFO, que vai para violeta. O erro VOLTA a ser vermelho
 *     justamente porque pode — a marca não disputa aquele matiz. O princípio é
 *     o mesmo nos dois temas: a cor da marca decide qual convenção ainda cabe.
 *
 *     O warning também sai do azul e vira âmbar. Ele era 200°, ou seja, azul —
 *     e com a marca em cyan viraria a própria marca.
 *   - Charts: oito séries da paleta de sintaxe do code-block, com variante por
 *     modo. Não saem mais da paleta deste tema — a razão está no bloco
 *     `--chart-*`, e é de contraste, não de estilo.
 *   - Radius, dimensões e shadows herdam de tokens.css (Default).
 *
 * O que este arquivo dizia antes, e o que a medição mostrou: "feedback colors
 * deslocam suavemente para o lado frio do espectro". Deslocavam, e chegaram
 * todos no mesmo lugar — `primary × info` a 0° de matiz NOS DOIS MODOS (a cor
 * de informação era o matiz da marca), `primary × warning` a 18°/14°, e ainda
 * `success` reprovando o piso de 4.5 no claro (4.46) e `destructive` no escuro
 * (4.07). Hoje a menor separação entre os cinco é 48° no claro e 62° no escuro.
 *
 * Contraste, mesma conta do Default — contraste(cor, composição(cor a 10%,
 * superfície)), sobre a página e sobre `--muted`, o pior dos dois:
 *
 *   claro   destructive 5.06 · success 4.80  (min 4.5)
 *           warning     3.68 · info    5.60  (min 3)
 *   escuro  destructive 5.13 · success 6.47  (min 4.5)
 *           warning     7.23 · info    5.37  (min 3)
 *
 * primary como texto na página: 5.02 no claro, 9.83 no escuro. Preenchido
 * contra o próprio foreground: 4.91 e 9.64.
 *
 * A paleta de gráficos deste tema já foi o pior caso do repositório: QUATRO das
 * cinco séries abaixo de 3:1 contra a página clara, e o par mais próximo a 4°.
 * Foi corrigida uma vez dentro da própria família fria e depois SUBSTITUÍDA — a
 * paleta de gráfico deixou de derivar da marca de cada tema e passou a ser a de
 * sintaxe do code-block, que tem variante por modo.
 *
 * A causa raiz era essa: uma paleta só, declarada no claro, servindo a dois
 * fundos opostos. Enquanto ela existisse, cada tema resolveria de novo o mesmo
 * problema — e o Default nem tinha resolvido, com uma série a 1.00 contra o
 * fundo escuro.
 *
 * O âmbar do claro é escuro (32%) pelo mesmo motivo do Warm: a página é quase
 * branca, ele precisa de 3:1, e amarelo escurecido dessatura para oliva — por
 * isso ele fica na faixa laranja-âmbar.
 *
 * Aplicado via classe `.tema-cold` no <html>. Dark mode combina com `.dark`.
 */

.tema-cold {
  /* Surfaces — tint azul muito sutil */
  --background: 210 30% 99%;
  --foreground: 215 25% 8%;
  --card: 210 30% 99%;
  --card-foreground: 215 25% 8%;
  --popover: 210 30% 99%;
  --popover-foreground: 215 25% 8%;

  /* Brand / Interactive — primary azul royal saturado; secondary/accent azul-gelo */
  --primary: 195 90% 32%;           /* #08769b — a marca escurecida até passar como TEXTO */
  --primary-foreground: 210 30% 98%;
  --secondary: 205 55% 92%;         /* azul-gelo claro */
  --secondary-foreground: 195 80% 22%;
  --muted: 210 20% 95%;
  --muted-foreground: 215 12% 42%;
  /* Valor CHEIO — ver a nota do warm. Resolvido para compor, a 20% sobre a
     página, o mesmo pálido opaco de antes. */
  --accent: 206 65% 68%;
  --accent-foreground: 195 80% 22%;

  /* Feedback — paleta fria */
  /* Os quatro `-foreground` são o texto corrido do contêiner colorido, e neste
     projeto valem `--foreground` — a regra da casa. São ponto de extensão: um
     tema derivado pode dar a cada um valor próprio. Ver tokens.css. */
  --destructive: 352 78% 40%;   /* #b6162c */
  --destructive-foreground: var(--foreground);
  --success: 150 75% 25%;       /* #107040 */
  --success-foreground: var(--foreground);
  --warning: 38 100% 32%;       /* #a36700 */
  --warning-foreground: var(--foreground);
  --info: 280 60% 42%;          /* #812bab */
  --info-foreground: var(--foreground);

  /* Structure */
  --border: 210 18% 88%;
  --input: 210 18% 56%;             /* 3.27:1 sobre --background; matiz frio preservado */
  --input-background: 210 30% 99%;
  --ring: 195 90% 38%;              /* acompanha o primary, mais claro */

  /* Charts — oito séries, com variante por MODO (o bloco escuro fica no fim do
     `.dark.tema-*`).

     Vêm da paleta de sintaxe do code-block, e a escolha é estrutural: ela já
     tinha valores por modo, enquanto a paleta de gráfico antiga era declarada só
     no claro e a MESMA cor precisava servir à página quase branca e ao fundo
     quase preto. Nessa janela, uma das séries do Default acabava com contraste
     1.00 contra o fundo escuro — a cor do próprio fundo, invisível.

     Medido nos três temas: pior contraste 7.32 no claro e 6.83 no escuro. A
     ordem não é arbitrária — cada série é a que MAIS se afasta das anteriores em
     matiz, então a menor separação dentro das cinco primeiras é 38°, e dentro
     das oito, 20°, que é o limite da paleta. Reordenar aproxima séries vizinhas.

     Os graus são de matiz em OKLCH, não em HSL. Dizer isso não é preciosismo:
     recalcular a partir dos números HSL declarados acima dá outros valores, e
     quem tentar conferir vai concluir que a conta está errada. HSL não é
     perceptualmente uniforme — 20° de matiz ali significam distâncias muito
     diferentes dependendo de onde se está na roda.

     Ficam no TEMA, e não em tokens.css: um tema derivado pode querer paleta
     própria de gráfico, e o contrato de tema é o lugar dessa liberdade. */
  --chart-1: 350 72% 36%;
  --chart-2: 190 88% 23%;
  --chart-3: 265 64% 41%;
  --chart-4: 145 62% 23%;
  --chart-5: 215 72% 34%;
  --chart-6: 25 88% 28%;
  --chart-7: 288 52% 36%;
  --chart-8: 200 85% 26%;

  /* Sidebar — tint frio */
  --sidebar: 210 30% 98%;
  --sidebar-foreground: 215 25% 8%;
  --sidebar-primary: 195 90% 32%;
  --sidebar-primary-foreground: 210 30% 98%;
  --sidebar-accent: 205 55% 92%;
  --sidebar-accent-foreground: 195 80% 22%;
  --sidebar-border: 210 18% 85%;
  --sidebar-ring: 195 90% 38%;

  /* Radius — a identidade de forma deste tema é o CANTO RETO: base zero.

     A base sozinha não basta, e é o detalhe que separa "quase quadrado" de
     quadrado: --radius-badge aponta para --radius-full, que é 9999px fixo e
     não deriva da base. Sem zerá-lo à mão, o tema reto teria badge em cápsula.

     Os degraus de baixo da escala passam por max(0px, …) no tokens.css
     justamente para este caso: sem isso, calc(0px - 6px) daria raio negativo,
     valor inválido que derruba a declaração em silêncio. */
  --radius: 0;
  --radius-badge: 0;
  /* O cartão também, e por um motivo que só aparece na conta: `--radius-xl` é o
     único degrau ADITIVO da escada (`base + 4px`), então ele não zera junto com
     a base como os de baixo, que passam por `max(0px, …)`. Um tema que se
     declara quadrado ficava com cartões de 4px — arredondados o suficiente para
     desmentir a própria identidade, e discretos o suficiente para ninguém
     notar. Mesma família do `--radius-badge`, que aponta para `--radius-full`. */
  --radius-card: 0;
}

/* Dark mode — combina `.dark.tema-cold` */
.dark.tema-cold {
  --background: 215 25% 9%;
  --foreground: 210 25% 96%;
  --card: 215 25% 9%;
  --card-foreground: 210 25% 96%;
  --popover: 215 25% 9%;
  --popover-foreground: 210 25% 96%;
  --primary: 195 100% 61%;          /* #38cdff — a marca, literal */
  --primary-foreground: 215 30% 10%;
  --secondary: 215 25% 18%;         /* azul-marinho escuro */
  --secondary-foreground: 205 55% 90%;
  --muted: 215 15% 16%;
  --muted-foreground: 210 12% 70%;
  /* Cheio, mesmo motivo. A 0.8 dá 4,77:1 com a tinta clara. */
  --accent: 214 35% 49%;
  --accent-foreground: 205 55% 90%;
  --destructive: 356 90% 74%;   /* #f88189 */
  --destructive-foreground: var(--foreground);
  --success: 148 60% 58%;       /* #54d490 */
  --success-foreground: var(--foreground);
  --warning: 45 92% 56%;        /* #f6c228 */
  --warning-foreground: var(--foreground);
  --info: 282 85% 76%;          /* #d78ef6 */
  --info-foreground: var(--foreground);
  --border: 215 15% 16%;
  --input: 215 15% 42%;             /* 3.22:1 sobre --background; matiz frio preservado */
  --input-background: 215 25% 9%;
  --ring: 195 100% 56%;
  --sidebar: 215 25% 9%;
  --sidebar-foreground: 210 25% 96%;
  --sidebar-primary: 195 100% 61%;
  --sidebar-primary-foreground: 215 30% 10%;
  --sidebar-accent: 215 25% 18%;
  --sidebar-accent-foreground: 205 55% 90%;
  --sidebar-border: 215 15% 16%;
  --sidebar-ring: 195 100% 56%;

  /* Charts — agora COM variante escura. Antes eram declarados só no bloco
     claro, e a mesma cor tinha de servir à página quase branca e ao fundo
     quase preto: no Default isso deixava uma série com contraste 1.00, a cor
     do próprio fundo. */
  --chart-1: 350 82% 80%;
  --chart-2: 190 72% 68%;
  --chart-3: 265 82% 82%;
  --chart-4: 145 52% 70%;
  --chart-5: 215 88% 78%;
  --chart-6: 25 88% 72%;
  --chart-7: 288 68% 82%;
  --chart-8: 200 80% 72%;
}

/*
 * ─── Densidades ───────────────────────────────────────────────────────────────
 * Ajusta o tamanho base de spacing do projeto, afetando proporcionalmente todo
 * token --spacing-* (e portanto toda classe .nds-* que os consome).
 *
 * Também ajusta as alturas tokenizadas (--height-*, --size-*) para que
 * botões/inputs/selects acompanhem a densidade.
 *
 * Aplicado via classe no <html>:
 *   default (sem classe)          — --spacing-base = 4px
 *   .densidade-condensado          — --spacing-base ≈ 3.2px (~80%)
 *   .densidade-confortavel         — --spacing-base ≈ 5px   (~125%)
 *
 * Pode combinar com qualquer tema de cor (.tema-warm, .tema-cold) e com .dark.
 */

/* ── Default — re-declara os valores de :root para garantir cascade
 *    correto ao voltar de condensado/confortável. Mesmos números de tokens.css. */
.densidade-default {
  --spacing-base: 0.25rem;         /* 4px */
  --height-sm: 1.75rem;            /* 28px */
  --height-default: 2rem;          /* 32px */

  --size-xs: 1.5rem;
  --size-sm: 1.75rem;
  --size-default: 2rem;
  --size-lg: 2.25rem;
  --size-xl: 2.5rem;
}

/* ── Condensado — interfaces densas, mais informação na tela ──────────────── */
.densidade-condensado {
  --spacing-base: 0.20rem;        /* 3.2px (80% do padrão) */

  /* Escada de quadrado (icon-only) + os dois degraus de caixa sem texto */
  --height-sm: 1.5rem;             /* 24px */
  --height-default: 1.75rem;       /* 28px */

  --size-xs: 1.25rem;
  --size-sm: 1.5rem;
  --size-default: 1.75rem;
  --size-lg: 2rem;
  --size-xl: 2.25rem;
}

/* ── Confortável — interfaces folgadas, mais respiro ──────────────────────── */
.densidade-confortavel {
  --spacing-base: 0.3125rem;      /* 5px (125% do padrão) */

  /* Escada de quadrado (icon-only) + os dois degraus de caixa sem texto */
  --height-sm: 2rem;               /* 32px */
  --height-default: 2.5rem;        /* 40px */

  --size-xs: 1.75rem;
  --size-sm: 2rem;
  --size-default: 2.5rem;
  --size-lg: 2.75rem;
  --size-xl: 3rem;
}

/*
 * ─── Fontes ───────────────────────────────────────────────────────────────────
 * Sobrescreve --font-family-active, que é consumido por --font-family.
 * Os @import das fontes ficam em tokens.css (carregados uma vez).
 *
 * Aplicado via classe no <html>:
 *   default (sem classe)  — Inter (padrão)
 *   .fonte-lexend          — Lexend (humanista, ampla, alta legibilidade)
 *   .fonte-pt-serif        — PT Serif (serifada clássica)
 *   .fonte-lxgw-wenkai     — LXGW WenKai TC (manuscrita tradicional chinesa/latina)
 *
 * Combina com qualquer tema de cor, densidade e light/dark.
 */

/* Default — re-declara para garantir cascade ao voltar de outra fonte */
.fonte-default {
  --font-family-active: 'Inter', sans-serif;
}

.fonte-lexend {
  --font-family-active: 'Lexend', sans-serif;
}

.fonte-pt-serif {
  --font-family-active: 'PT Serif', Georgia, serif;
}

.fonte-lxgw-wenkai {
  --font-family-active: 'LXGW WenKai TC', 'Kaiti', cursive;
}
